insert into public.project_milestones (id, slug, position, title, description, target_day, tasks) values ('ac1e828c-2ebe-44ae-a49a-5bc3fce67135', 'documentation', 12, 'Documentation', 'Make the project interview-ready: architecture docs, API docs and a demo.', 58, '[{"id":"documentation-1","title":"Architecture diagram + decisions log"},{"id":"documentation-2","title":"Swagger/OpenAPI docs"},{"id":"documentation-3","title":"README with setup and screenshots"},{"id":"documentation-4","title":"Record a 5-minute demo video"}]'::jsonb) on conflict (slug) do update set position = excluded.position, title = excluded.title, description = excluded.description, target_day = excluded.target_day, tasks = excluded.tasks;
